            if (nextHeight > height) {
                // Calculate the maximum area for the current bar
                area = height * (i + 1);

                // Check if the maximum area for the current bar is greater than the maximum area so far
                if (area > maxArea) {
                    // Update the maximum area
                    maxArea = area;
                }
            }
        }
    }

